import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';
import { ScrollArea } from '@/components/ui/scroll-area';
import { 
  CheckCircle, 
  Circle, 
  XCircle, 
  StopCircle, 
  Clock, 
  Eye,
  ArrowRight
} from 'lucide-react';
import { useSocket, RobotkezStep } from '@/context/SocketContext';
import { cn } from '@/lib/utils';
import { toast } from 'sonner';

export function LiveExecutionMonitor() {
  const { robotkezPlan, robotkezSteps, socket } = useSocket();
  const [selectedScreenshot, setSelectedScreenshot] = useState<string | null>(null);

  if (!robotkezPlan) return null;

  const totalSteps = robotkezSteps.length;
  const completedSteps = robotkezSteps.filter(s => s.status === 'completed').length;
  const progress = totalSteps > 0 ? (completedSteps / totalSteps) * 100 : 0;
  const isRunning = robotkezSteps.some(s => s.status === 'working');
  const isFinished = completedSteps === totalSteps || robotkezSteps.some(s => s.status === 'error');

  const handleAbort = () => {
    if (socket) {
      socket.emit('robotkez:abort');
      toast.warning('Megszakítás elküldve...');
    }
  };

  const getStatusIcon = (status: RobotkezStep['status']) => {
    switch (status) {
      case 'completed': return <CheckCircle className="w-4 h-4 text-emerald-500" />;
      case 'working': return <div className="w-4 h-4 border-2 border-primary border-t-transparent rounded-full animate-spin" />;
      case 'error': return <XCircle className="w-4 h-4 text-red-500" />;
      default: return <Circle className="w-4 h-4 text-zinc-600" />;
    }
  };

  return (
    <div className="space-y-4 animate-in fade-in slide-in-from-top-4 duration-500">
      <Card className="glass-panel border-primary/20 bg-primary/5">
        <CardHeader className="p-4 border-b border-white/5 flex flex-row items-center justify-between">
          <div className="space-y-1">
            <CardTitle className="text-sm font-bold tracking-widest uppercase flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-primary animate-pulse" />
              Live Execution Monitor
            </CardTitle>
            <p className="text-[10px] font-mono text-zinc-500">MISSION_ID: {robotkezPlan.taskId}</p>
          </div>
          
          {!isFinished && (
            <Button 
              variant="destructive" 
              size="sm" 
              className="h-8 gap-2 bg-red-500/20 hover:bg-red-500 text-red-500 hover:text-white border border-red-500/30"
              onClick={handleAbort}
            >
              <StopCircle size={14} />
              STOP
            </Button>
          )}
        </CardHeader>
        
        <CardContent className="p-4 space-y-4">
          {/* Progress Section */}
          <div className="space-y-2">
            <div className="flex justify-between text-[10px] font-mono text-zinc-400 uppercase">
              <span>Progress</span>
              <span>{Math.round(progress)}% ({completedSteps}/{totalSteps})</span>
            </div>
            <Progress value={progress} className="h-1.5 bg-white/5" />
          </div>

          {/* Steps List */}
          <ScrollArea className="h-[300px] pr-4">
            <div className="space-y-3">
              {robotkezSteps.map((step, idx) => (
                <div 
                  key={idx} 
                  className={cn(
                    "flex items-start gap-3 p-3 rounded-xl border transition-all duration-300",
                    step.status === 'working' ? "bg-primary/10 border-primary/30" : 
                    step.status === 'completed' ? "bg-white/5 border-emerald-500/20" :
                    "bg-black/20 border-white/5 opacity-60"
                  )}
                >
                  <div className="mt-0.5 shrink-0">
                    {getStatusIcon(step.status)}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className={cn(
                      "text-xs font-medium leading-none",
                      step.status === 'completed' ? "text-emerald-400" : "text-zinc-200"
                    )}>
                      {step.description}
                    </p>
                    {step.error && (
                      <p className="text-[10px] text-red-400 mt-1 font-mono">ERR: {step.error}</p>
                    )}
                  </div>
                  {step.screenshot && (
                    <Button 
                      variant="ghost" 
                      size="icon" 
                      className="h-6 w-6 rounded-full hover:bg-white/10"
                      onClick={() => setSelectedScreenshot(step.screenshot || null)}
                    >
                      <Eye size={12} className="text-zinc-400" />
                    </Button>
                  )}
                </div>
              ))}
            </div>
          </ScrollArea>

          {/* Estimated Time */}
          <div className="pt-2 border-t border-white/5 flex items-center justify-between text-[10px] font-mono text-zinc-500 uppercase">
            <div className="flex items-center gap-1.5">
              <Clock size={12} />
              <span>Est. Remaining: {Math.round((robotkezPlan.plan.estimatedDuration * (1 - progress/100)) / 1000)}s</span>
            </div>
            {isFinished && (
              <Button 
                variant="link" 
                size="sm" 
                className="h-auto p-0 text-[10px] text-zinc-400 hover:text-primary"
                onClick={() => { /* Potential clear/archive logic */ }}
              >
                DISMISS MONITOR
              </Button>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Screenshot Modal/Overlay */}
      {selectedScreenshot && (
        <div 
          className="fixed inset-0 z-[100] bg-black/90 flex items-center justify-center p-8 animate-in fade-in duration-300"
          onClick={() => setSelectedScreenshot(null)}
        >
          <div className="relative max-w-5xl w-full max-h-full flex flex-col items-center gap-4">
            <img 
              src={selectedScreenshot.startsWith('data:') ? selectedScreenshot : `data:image/png;base64,${selectedScreenshot}`} 
              alt="Step Screenshot" 
              className="max-w-full max-h-[85vh] rounded-lg border border-white/10 shadow-2xl"
            />
            <Button variant="outline" className="bg-white/5 border-white/10 text-white hover:bg-white/10">
              CLOSE PREVIEW
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

import {
  createContext,
  useContext,
  useEffect,
  useReducer,
  useState,
  type ReactNode,
} from "react";
import { io, type Socket } from "socket.io-client";

export type LogType = "info" | "error" | "success";

export interface LogEntry {
  id: string;
  message: string;
  type: LogType;
  timestamp: number;
  source?: string;
}

export type AgentStatusPayload = "idle" | "working" | "error";

export interface RobotkezStep {
  index: number;
  status: 'pending' | 'working' | 'completed' | 'error';
  description: string;
  screenshot?: string;
  error?: string;
}

export interface RobotkezPlan {
  taskId: string;
  plan: {
    plan: RobotkezStep[];
    estimatedDuration: number;
  };
}

export interface AgentStatusEntry {
  name: string;
  status: AgentStatusPayload;
  taskDescription?: string;
  lastUpdated: number;
}

interface SocketState {
  isConnected: boolean;
  logs: LogEntry[];
  agents: Map<string, AgentStatusEntry>;
  robotkezPlan: RobotkezPlan | null;
  robotkezSteps: RobotkezStep[];
}

type SocketAction =
  | { type: "connect" }
  | { type: "disconnect" }
  | { type: "log"; payload: Omit<LogEntry, "id"> }
  | {
      type: "agent_update";
      payload: {
        agentName: string;
        status: AgentStatusPayload;
        taskDescription?: string;
      };
    }
  | { type: "robotkez_plan"; payload: RobotkezPlan }
  | { type: "robotkez_step"; payload: Partial<RobotkezStep> & { index: number } }
  | { type: "robotkez_clear" };

const MAX_LOGS = 200;
let logIdCounter = 0;

function socketReducer(state: SocketState, action: SocketAction): SocketState {
  switch (action.type) {
    case "connect":
      return { ...state, isConnected: true };
    case "disconnect":
      return { ...state, isConnected: false };
    case "log": {
      const newLog: LogEntry = {
        ...action.payload,
        id: `log-${++logIdCounter}`,
      };
      const logs = [newLog, ...state.logs].slice(0, MAX_LOGS);
      return { ...state, logs };
    }
    case "agent_update": {
      const { agentName, status, taskDescription } = action.payload;
      const agents = new Map(state.agents);
      agents.set(agentName, {
        name: agentName,
        status,
        taskDescription,
        lastUpdated: Date.now(),
      });
      return { ...state, agents };
    }
    case "robotkez_plan": {
      return { 
        ...state, 
        robotkezPlan: action.payload,
        robotkezSteps: action.payload.plan.plan.map((s, i) => ({ ...s, index: i, status: 'pending' }))
      };
    }
    case "robotkez_step": {
      const steps = [...state.robotkezSteps];
      const idx = action.payload.index;
      if (steps[idx]) {
        steps[idx] = { ...steps[idx], ...action.payload };
      }
      return { ...state, robotkezSteps: steps };
    }
    case "robotkez_clear": {
      return { ...state, robotkezPlan: null, robotkezSteps: [] };
    }
    default:
      return state;
  }
}

const initialState: SocketState = {
  isConnected: false,
  logs: [],
  agents: new Map(),
  robotkezPlan: null,
  robotkezSteps: []
};

interface SocketContextValue extends SocketState {
  socket: Socket | null;
}

const SocketContext = createContext<SocketContextValue | null>(null);

const SOCKET_URL =
  import.meta.env.VITE_SOCKET_URL ||
  (import.meta.env.DEV ? "http://localhost:3000" : window.location.origin);

export function SocketProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(socketReducer, initialState);
  const [socketInstance, setSocketInstance] = useState<Socket | null>(null);

  useEffect(() => {
    const socket = io(SOCKET_URL, {
      path: "/socket.io",
      transports: ["websocket", "polling"],
      reconnection: true,
      reconnectionAttempts: 5,
      reconnectionDelay: 1000,
    });

    setSocketInstance(socket);

    // Expose socket to window for E2E testing
    if (typeof window !== 'undefined') {
      (window as any).__BRUNELLA_SOCKET__ = socket;
    }

    const getErrorMessage = (error: unknown): string => {
      if (error instanceof Error) return error.message;
      if (typeof error === "string") return error;
      if (typeof error === "object" && error !== null) {
        const maybe = (error as { message?: unknown }).message;
        if (typeof maybe === "string") return maybe;
      }
      return "ismeretlen hiba";
    };

    const log = (message: string, type: LogType = "info") => {
      dispatch({
        type: "log",
        payload: {
          message,
          type,
          timestamp: Date.now(),
          source: "Socket",
        },
      });
    };

    const onConnect = () => {
      dispatch({ type: "connect" });
      log("Socket csatlakozva ✅", "success");
    };

    const onDisconnect = (reason: unknown) => {
      dispatch({ type: "disconnect" });
      const r = typeof reason === "string" ? reason : "unknown";
      // socket.io reasons: 'transport close', 'io client disconnect', 'io server disconnect', ...
      log(`Socket bontva: ${r}`, "error");
    };

    const onConnectError = (error: unknown) => {
      log(`Socket kapcsolódási hiba: ${getErrorMessage(error)}`, "error");
    };

    const onError = (error: unknown) => {
      const msg = getErrorMessage(error);
      log(`Socket hiba: ${msg}`, "error");
    };

    socket.on("connect", onConnect);
    socket.on("disconnect", onDisconnect);
    socket.on("connect_error", onConnectError);
    socket.on("error", onError);

    // Reconnect UX (manager events)
    const manager = socket.io;
    const onReconnectAttempt = (attempt: unknown) => {
      const n = typeof attempt === "number" ? attempt : undefined;
      log(`Socket újrapróbálkozás...${n ? ` (#${n})` : ""}`);
    };
    const onReconnect = (attempt: unknown) => {
      const n = typeof attempt === "number" ? attempt : undefined;
      log(`Socket újracsatlakozott ✅${n ? ` (#${n})` : ""}`, "success");
    };
    const onReconnectError = (_err: unknown) => {
      log("Socket újracsatlakozás sikertelen (próbálkozás fut)", "error");
    };
    const onReconnectFailed = () => {
      log("Socket újracsatlakozás feladva (max próbálkozás)", "error");
    };

    manager.on("reconnect_attempt", onReconnectAttempt);
    manager.on("reconnect", onReconnect);
    manager.on("reconnect_error", onReconnectError);
    manager.on("reconnect_failed", onReconnectFailed);

    socket.on(
      "system:log",
      (data: {
        message: string;
        type: LogType;
        timestamp?: number;
        source?: string;
      }) => {
        dispatch({
          type: "log",
          payload: {
            message: data.message,
            type: data.type ?? "info",
            timestamp: data.timestamp ?? Date.now(),
            source: data.source,
          },
        });
      },
    );

          socket.on(
            "agent:update",
            (data: {
              agentName: string;
              status: AgentStatusPayload;
              taskDescription?: string;
            }) => {
              if (data.agentName && data.status) {
                dispatch({
                  type: "agent_update",
                  payload: {
                    agentName: data.agentName,
                    status: data.status,
                    taskDescription: data.taskDescription,
                  },
                });
              }
            },
          );
    
          socket.on("robotkez:plan", (data: RobotkezPlan) => {
            dispatch({ type: "robotkez_plan", payload: data });
          });
    
          socket.on("robotkez:step", (data: Partial<RobotkezStep> & { index: number }) => {
            dispatch({ type: "robotkez_step", payload: data });
          });
    
          socket.on("robotkez:aborted", () => {
            dispatch({ type: "robotkez_clear" });
          });
    return () => {
      socket.off("connect", onConnect);
      socket.off("disconnect", onDisconnect);
      socket.off("connect_error", onConnectError);
      socket.off("error", onError);

      manager.off("reconnect_attempt", onReconnectAttempt);
      manager.off("reconnect", onReconnect);
      manager.off("reconnect_error", onReconnectError);
      manager.off("reconnect_failed", onReconnectFailed);

      socket.off("system:log");
      socket.off("agent:update");
      socket.disconnect();
      setSocketInstance(null);
    };
  }, []);

  const value: SocketContextValue = {
    ...state,
    socket: socketInstance,
  };

  return (
    <SocketContext.Provider value={value}>{children}</SocketContext.Provider>
  );
}

export function useSocket() {
  const ctx = useContext(SocketContext);
  if (!ctx) throw new Error("useSocket must be used within SocketProvider");
  return ctx;
}

