import {
  createContext,
  useContext,
  useEffect,
  useReducer,
  useState,
  type ReactNode,
} from "react";
import { io, type Socket } from "socket.io-client";

export type LogType = "info" | "error" | "success";

export interface LogEntry {
  id: string;
  message: string;
  type: LogType;
  timestamp: number;
  source?: string;
}

export type AgentStatusPayload = "idle" | "working" | "error";

export interface RobotkezStep {
  index: number;
  status: 'pending' | 'working' | 'completed' | 'error';
  description: string;
  screenshot?: string;
  error?: string;
}

export interface RobotkezPlan {
  taskId: string;
  plan: {
    plan: RobotkezStep[];
    estimatedDuration: number;
  };
}

export interface AgentStatusEntry {
  name: string;
  status: AgentStatusPayload;
  taskDescription?: string;
  lastUpdated: number;
}

export interface ChatterEntry {
  id: string;
  sender: string;
  receiver?: string;
  message: string;
  context?: any;
  timestamp: number;
}

interface SocketState {
  isConnected: boolean;
  logs: LogEntry[];
  agents: Map<string, AgentStatusEntry>;
  chatter: ChatterEntry[];
  robotkezPlan: RobotkezPlan | null;
  robotkezSteps: RobotkezStep[];
}

type SocketAction =
  | { type: "connect" }
  | { type: "disconnect" }
  | { type: "log"; payload: Omit<LogEntry, "id"> }
  | { type: "chatter"; payload: Omit<ChatterEntry, "id"> }
  | {
      type: "agent_update";
      payload: {
        agentName: string;
        status: AgentStatusPayload;
        taskDescription?: string;
      };
    }
  | { type: "robotkez_plan"; payload: RobotkezPlan }
  | { type: "robotkez_step"; payload: Partial<RobotkezStep> & { index: number } }
  | { type: "robotkez_clear" };

const MAX_LOGS = 200;
const MAX_CHATTER = 100;
let logIdCounter = 0;
let chatterIdCounter = 0;

function socketReducer(state: SocketState, action: SocketAction): SocketState {
  switch (action.type) {
    case "connect":
      return { ...state, isConnected: true };
    case "disconnect":
      return { ...state, isConnected: false };
    case "log": {
      const newLog: LogEntry = {
        ...action.payload,
        id: `log-${++logIdCounter}`,
      };
      const logs = [newLog, ...state.logs].slice(0, MAX_LOGS);
      return { ...state, logs };
    }
    case "chatter": {
      const newChatter: ChatterEntry = {
        ...action.payload,
        id: `chat-${++chatterIdCounter}`,
      };
      const chatter = [newChatter, ...state.chatter].slice(0, MAX_CHATTER);
      return { ...state, chatter };
    }
    case "agent_update": {
      const { agentName, status, taskDescription } = action.payload;
      const agents = new Map(state.agents);
      agents.set(agentName, {
        name: agentName,
        status,
        taskDescription,
        lastUpdated: Date.now(),
      });
      return { ...state, agents };
    }
    case "robotkez_plan": {
      return { 
        ...state, 
        robotkezPlan: action.payload,
        robotkezSteps: action.payload.plan.plan.map((s, i) => ({ ...s, index: i, status: 'pending' }))
      };
    }
    case "robotkez_step": {
      const steps = [...state.robotkezSteps];
      const idx = action.payload.index;
      if (steps[idx]) {
        steps[idx] = { ...steps[idx], ...action.payload };
      }
      return { ...state, robotkezSteps: steps };
    }
    case "robotkez_clear": {
      return { ...state, robotkezPlan: null, robotkezSteps: [] };
    }
    default:
      return state;
  }
}

