  name = 'MarketIntel';
  role = 'Competitor Price Monitoring & Market Analysis';
  description = 'Automated competitor website scraping, price tracking, and trend analysis with LanceDB storage';
  capabilities = [
    'competitor_scraping',
    'price_extraction',
