      const highestPrice = Math.max(...priceValues);

      const priceChange = ((currentPrice - averagePrice) / averagePrice) * 100;

      let trend: 'increasing' | 'decreasing' | 'stable';
      if (priceChange > 5) {
        trend = 'increasing';
      } else if (priceChange < -5) {
        trend = 'decreasing';
      } else {
        trend = 'stable';
      }

      trends.push({
        productName,
