    }
    return undefined;
  }

  private extractPriceRange(task: string): { min: number; max: number } | undefined {
    const match = task.match(/(\d+)\s*-\s*(\d+)/);
    if (match) {
      return {
        min: parseInt(match[1], 10),
        max: parseInt(match[2], 10),
      };
    }
    return undefined;
  }

  private getDefaultCompetitors(category: string): string[] {
