                    socketStatusMap={socketStatusMap}
                    handleExecuteAgent={handleExecuteAgent}
                    logs={logs}
                  />
                )}

                {activeItem?.component}
              </div>
            </div>
          </main>
        </div>
      </div>
      </LayoutProvider>
    </>
  );
}

