import { navigationRegistry } from "@/lib/navigation";
import { DynamicSidebar } from "@/components/dashboard/DynamicSidebar";
import { WidgetGrid } from "@/components/dashboard/WidgetGrid";
import { useExperiments } from "@/context/ExperimentContext";
import { LayoutProvider, useLayout } from "@/lib/layout/LayoutContext";

export function MissionControlLayout() {
  const [activeTab, setActiveTab] = useState<string>("dashboard");
  const { layoutDensity } = useExperiments();
  const { currentLayout, setLayoutMode } = useLayout();
  // registryAgents and its loading logic are now managed by useSystemSignal or individual widgets
  // const [registryAgents, setRegistryAgents] = useState<RegistryAgent[]>([]);
  // const [isLoadingAgents, setIsLoadingAgents] = useState(true);
  const [isBooting, setIsBooting] = useState(true);
  const { logs, agents, isConnected, healthStatus } = useSystemSignal();

  useEffect(() => {
    setIsLoadingAgents(true);
    getRegistry()
      .then((r) => setRegistryAgents(r.agents || []))
      .catch(() => setRegistryAgents([]))
      .finally(() => setIsLoadingAgents(false));
  }, []);

  const socketStatusMap = agents;

  const handleExecuteAgent = async (agentName: string, task: string) => {
    try {
      toast.info(`${agentName} initiating protocol...`);
      await executeAgent(agentName, task);
      toast.success("Protocol execution verified");
    } catch (e: unknown) {
      toast.error(e instanceof Error ? e.message : "System failure");
    }
  };

  const activeItem = navigationRegistry.getItem(activeTab);

  return (
    <>
      {isBooting && <SystemBootSequence onComplete={() => setIsBooting(false)} />}
      <LayoutProvider>
