            gridTemplateAreas: currentLayout.gridTemplateAreas.map(area => `'${area}'`).join(' '),
            gridTemplateColumns: currentLayout.gridTemplateColumns || '1fr',
            gridTemplateRows: currentLayout.gridTemplateRows || 'auto 1fr auto',
