import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Zap, Pause, Play, XCircle, RefreshCcw } from "lucide-react";
import { toast } from "sonner";
import { cancelTask, retryTask, pauseTask, resumeTask } from "@/lib/apiService";
import { useSystemSignal } from "@/hooks/useSystemSignal";

export function ProcessControlWidget() {
  const { tasks } = useSystemSignalStore((state) => ({
    tasks: state.tasks,
  }));
  const { refetchData } = useSystemSignal();

  // Filter for active/pending tasks (mock for now, actual logic needed)
  const activeTasks = tasks.filter(task => task.status === "running" || task.status === "pending");

  const handleControlAction = async (taskId: number, action: 'pause' | 'resume' | 'kill' | 'retry') => {
    try {
      switch (action) {
        case 'pause':
          await pauseTask(taskId);
          toast.success(`Feladat ${taskId} szüneteltetve.`);
          break;
        case 'resume':
          await resumeTask(taskId);
          toast.success(`Feladat ${taskId} folytatva.`);
          break;
        case 'kill':
          await cancelTask(taskId);
          toast.success(`Feladat ${taskId} leállítva.`);
          break;
        case 'retry':
          await retryTask(taskId);
          toast.success(`Feladat ${taskId} újrapróbálva.`);
          break;
        default:
          toast.error(`Ismeretlen akció: ${action}`);
          return;
      }
      refetchData(); // Refresh tasks after action
    } catch (error: any) {
      toast.error(`Sikertelen akció ${action} a feladaton ${taskId}: ${error.message}`);
    }
  };

  return (
    <Card className="h-full">
      <CardHeader>
        <CardTitle className="text-xl font-bold flex items-center gap-2">
          <Zap size={20} className="text-primary" /> Folyamatvezérlés
        </CardTitle>
      </CardHeader>
      <CardContent className="h-[calc(100%-70px)] overflow-y-auto custom-scrollbar">
        {activeTasks.length === 0 ? (
          <p className="text-sm text-zinc-500">Nincsenek aktív vagy függőben lévő feladatok.</p>
        ) : (
          <div className="space-y-4">
            {activeTasks.map((task) => (
              <div key={task.id} className="flex items-center justify-between p-3 border border-white/10 rounded-lg bg-black/10">
                <div className="flex flex-col">
                  <span className="text-sm font-semibold text-white">{task.description}</span>
                  <span className="text-xs text-zinc-500">Ügynök: {task.agent}</span>
                  <span className="text-xs text-zinc-600">Státusz: {task.status}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Button variant="ghost" size="sm" onClick={() => handleControlAction(task.id, 'pause')}><Pause size={16} /></Button>
                  <Button variant="ghost" size="sm" onClick={() => handleControlAction(task.id, 'resume')}><Play size={16} /></Button>
                  <Button variant="ghost" size="sm" onClick={() => handleControlAction(task.id, 'kill')}><XCircle size={16} /></Button>
                  <Button variant="ghost" size="sm" onClick={() => handleControlAction(task.id, 'retry')}><RefreshCcw size={16} /></Button>
                </div>
              </div>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

export default ProcessControlWidget;

