  async resumeTask(taskId: number): Promise<boolean> {
    const task = this.taskQueue.find((t) => t.id === taskId);
    if (!task) return false;
    if (task.status === "paused") {
      task.status = "pending";
      await updateTaskStatus(taskId, "pending", "Resumed by user");
