   * Edge állapot lekérdezése
   */
  getEdgeStatus(): {
    enabled: boolean;
    healthy: boolean;
    tunnelConnected: boolean;
  } {
    return {
      enabled: this.edgeConfig.enabled,
      healthy: this.edgeProxy?.isEdgeHealthy?.() || false,
      tunnelConnected: this.edgeProxy?.isTunnelConnected?.() || false,
    };
