import { globalErrorHandler } from "./middleware/errorHandler.js";
import {
  getPrometheusContentType,
  getPrometheusMetrics,
  initMetrics,
  recordHttpRequest,
} from "../utils/metrics.js";
import { createTelemetryRouter } from "./telemetryRoutes.js";
