            const msg = e instanceof Error ? e.message : String(e);
            logger.error(`Dashboard status API error: ${msg}`);
            res.status(500).json({ status: 'ERROR', error: msg, timestamp: new Date().toISOString() });
        }
    });

    return router;
}

